const {test}=require('node:test'),assert=require('node:assert/strict');
test('Halloween pack contains thirty unique reusable recipes and six balanced families',async()=>{const {CREATURES,FAMILIES,PACK}=await import('../halloween/catalog.mjs');assert.equal(CREATURES.length,30);assert.equal(new Set(CREATURES.map(c=>c.id)).size,30);for(const f of FAMILIES)assert.equal(CREATURES.filter(c=>c.family===f).length,5);assert.equal(PACK.variants.length,3);assert.deepEqual(JSON.parse(JSON.stringify(PACK)),PACK);for(const c of CREATURES){assert(c.height>0&&Number.isFinite(c.height));assert(c.story&&c.shape&&c.motion);}});
test('all 90 models animate with finite transforms and preserve their pose when paused',async()=>{const {CREATURES}=await import('../halloween/catalog.mjs'),{makeCreature,animateCreature}=await import('../halloween/models.mjs');for(let variant=0;variant<3;variant++)for(const s of CREATURES){const m=makeCreature(s,variant);for(const mode of ['idle','walk','greet'])for(let frame=0;frame<12;frame++)animateCreature(m,1/30,mode);m.updateMatrixWorld(true);m.traverse(o=>assert(o.matrixWorld.elements.every(Number.isFinite),s.id));const before=JSON.stringify(m.userData.body.toJSON());animateCreature(m,1,'walk',true);assert.equal(JSON.stringify(m.userData.body.toJSON()),before,s.id);}});
